query:
SELECT DISTINCT ?item ?matchedLabel ?en ?zh ?description ?kind WHERE {
          VALUES ?matchedLabel { "Galois group"@en "Galois theory"@en "Gram-Schmidt process"@en "Hermitian matrix"@en "Jordan normal form"@en "algebraic extension"@en "basis"@en "bilinear form"@en "characteristic polynomial"@en "coefficient"@en "commutative ring"@en "convergence"@en "cross product"@en "degree"@en "determinant"@en "diagonal matrix"@en "diagonalization"@en "dimension"@en "dot product"@en "dual space"@en "eigenspace"@en "eigenvalue"@en "eigenvector"@en "factorization"@en "field"@en "field extension"@en "free module"@en "fundamental theorem of algebra"@en "galois group"@en "galois theory"@en "gram-schmidt process"@en "hermitian matrix"@en "ideal"@en "identity matrix"@en "inner product"@en "integral domain"@en "inverse matrix"@en "irreducible polynomial"@en "jordan normal form"@en "limit"@en "linear combination"@en "linear dependence"@en "linear independence"@en "linear map"@en "linear operator"@en "linear transformation"@en "matrix"@en "maximal ideal"@en "minimal polynomial"@en "module"@en "monomial"@en "multiplicity"@en "norm"@en "orthogonal complement"@en "orthogonal matrix"@en "orthogonality"@en "orthonormal basis"@en "polynomial"@en "positive definite"@en "positive semidefinite"@en "prime ideal"@en "principal ideal"@en "projection"@en "quadratic form"@en "quotient ring"@en "rank"@en "ring"@en "root"@en "sequence"@en "singular matrix"@en "singular value decomposition"@en "span"@en "spectral theorem"@en "subfield"@en "subring"@en "subsequence"@en "subspace"@en "symmetric matrix"@en "tensor"@en "tensor product"@en "trace"@en "transpose"@en "triangular matrix"@en "unitary matrix"@en "vector space"@en }
          ?item (rdfs:label|skos:altLabel) ?matchedLabel.
          OPTIONAL { ?item rdfs:label ?en. FILTER(LANG(?en)="en") }
          OPTIONAL { ?item rdfs:label ?zh. FILTER(LANG(?zh) IN ("zh-hans","zh-cn","zh")) }
          OPTIONAL { ?item schema:description ?description. FILTER(LANG(?description)="en") }
          OPTIONAL { ?item wdt:P31 ?kind }
        }
